import React from 'react';
import Header from '../components/Header';
import Footer from '../components/Footer';
import LoginForm from '../components/login/LoginForm';
import { Link } from 'react-router-dom';


const Login = () => {
    return (
        <div className="bg-background text-on-background min-h-screen flex flex-col">
            <Header />

            {/* Main Content */}
            <main className="flex-grow flex items-center justify-center px-margin-mobile md:px-margin-desktop pt-20 pb-1">
                <div className="w-full max-w-[440px] flex flex-col gap-1">
                    {/* Login Card */}
                    <div className="bg-surface-container-lowest border border-outline-variant rounded-lg p-5 md:p-6 shadow-sm">
                        <div className="text-center mb-4">
                            <h1 className="font-headline-lg text-headline-lg text-primary mb-2">Welcome Back</h1>
                            <p className="font-body-md text-body-md text-on-surface-variant">Access your secure dashboard</p>
                        </div>
                        <LoginForm />
                    </div>

                    {/* Footer Link */}
                    <div className="text-center">
                        <p className="font-body-sm text-body-sm text-on-surface-variant">
                            Don't have an account? 
                            <Link to="/signup" className="text-secondary font-semibold hover:underline">Sign Up</Link>
                        </p>
                    </div>
                </div>
            </main>

            <Footer />
        </div>
    );
};

export default Login;
